/* Local production alpha. Server responses are the authorization boundary.
   No passwords, draft answers or record payloads are persisted in browser storage. */
"use strict";
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const main = $("#main");
const esc = (value) => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const S = { user:null, catalog:null, tab:"arr", entries:[], selected:null, draft:null, page:0, busy:false, filters:{}, loginMode:"operator" };
const STAGES = ["Receiving and Sorting","Cleaning / Decontamination","Inspection","Functional Testing","Repair / Reassembly","Final Quality Review","Packaging"];
const PRODUCTS = ["EP catheters","Vessel-sealing devices","Ultrasonic devices","Ablation devices","ECG products","Pulse-oximetry products","Trocars","Shaver products","Suture passers","Compression sleeves","Air-transfer mattresses"];
const CATEGORIES = ["Equipment","Logistical","Ergonomic","Training","Teamwork","Safety","Motivation/Enthusiasm/Energy","Other"];
function badgeRequested(){return new URLSearchParams(window.location.search).has('username');}
function requestedAssociateUsername(){const value=new URLSearchParams(window.location.search).get("username")?.trim()||"";return /^person-(?:[1-9]|[12]\d|30)$/.test(value)?value:(badgeRequested()?"":"person-1");}
function clearBadgeRequest(){const url=new URL(location.href);url.searchParams.delete('username');history.replaceState(null,'',url);}
function badgeConfirmation(){
 const card=$('.login-card'),hero=$('.hero');if(!card||!hero)return;
 const modal=document.createElement('dialog');modal.className='badge-confirmation';modal.setAttribute('aria-labelledby','badge-confirm-title');
 card.querySelector('h2').id='badge-confirm-title';card.querySelector('h2').textContent='Confirm your badge sign-in';
 const note=document.createElement('p');note.className='notice-line';note.textContent=requestedAssociateUsername()?'Badge scanned: '+requestedAssociateUsername()+'. Confirm or edit the username and enter that account’s password. Any previous account will not be used here.':'This badge username is invalid. Enter your intended demo username and password; no default account was selected.';card.querySelector('h2').after(note);
 $('.segmented',card).hidden=true;
 const cancel=document.createElement('button');cancel.type='button';cancel.textContent='Cancel badge sign-in';cancel.onclick=()=>{modal.close();hero.append(card);modal.remove();cancel.remove();};card.append(cancel);
 modal.append(card);main.append(modal);modal.oncancel=e=>{e.preventDefault();cancel.click();};modal.showModal();
}

const labels = {workDate:"Work date",shift:"Shift",stage:"Production stage",product:"Product family",team:"Team / work group",entryType:"Check-in type",mood:"Starting outlook",readiness:"Readiness",sopClarity:"SOP clarity",resources:"Tools and information",helpNeeded:"Would assistance help?",helpDetail:"Assistance detail",safetyConcern:"Immediate safety / quality concern",concernDetail:"Work-related concern",note:"Work note",experience:"Shift experience",quality:"Quality confidence",safety:"Safety confidence",workload:"Workload achievability",teamSupport:"Team support",pride:"Pride in workmanship",units:"Mfg. Associate-reported units (estimate)",downtimeCategory:"Interruption category",interruptionMinutes:"Approximate interruption minutes",challenges:"Work challenges",workedWell:"What worked well",improvement:"Improvement idea",recognitionPeople:"Teammates who helped",interruptions:"Interruption categories",recognition:"Specific helpful action",segmentStart:"Segment start",segmentEnd:"Segment end",qualityStatus:"Quality / safety status",qualityConcern:"Quality concern requiring follow-up",newStage:"Next production stage",newProduct:"Next product family",categories:"Proposal categories",proposal:"Original proposal",estimatedCost:"Estimated implementation cost",expectedValue:"Expected benefit",expectedResult:"Expected production result",supporters:"Other team support (requester perspective)"};
const entryTypeLabel = x => ({bod:"Beginning of shift",eod:"End of shift",changeover:"Product / station changeover"}[x] || x || "Check-in");
const isOperator = () => S.user?.role === "operator";
const isLead = () => ["reviewer","lead"].includes(S.user?.role);
const canManage = () => S.user?.role === "manager" || S.catalog?.capabilities?.operationalManager === true || S.user?.operationalManager === true || S.user?.roles?.includes("manager");
function associateLabel(person){const profile=person?.profile;return profile?`${profile.firstName} ${profile.lastName} (${person.username})`:person?.username||person?.id||'';}
function associateLabelById(value){const person=(S.catalog?.operators||[]).find(p=>p.id===value||p.username===value);return person?associateLabel(person):value||'Fictional Mfg. Associate';}
function datePacific(d = new Date()) {return new Intl.DateTimeFormat("en-CA",{timeZone:"America/Los_Angeles",year:"numeric",month:"2-digit",day:"2-digit"}).format(d);}
function priorDate(s, days){const d=new Date(s+"T12:00:00Z");d.setUTCDate(d.getUTCDate()-days);return d.toISOString().slice(0,10);}
function defaultFilters(){const to=datePacific();return {from:priorDate(to,13),to,hideReviewed:localStorage.getItem("production-hide-reviewed:"+S.user?.id)==="true",dataSource:"all",hideCompleted:true};}
let saveFlashTimer=null;
function showSaveFlash(message){const flash=$('#save-flash');if(!flash)return false;const text=String(message).replace(/\.$/,'');$('.save-flash-top',flash).textContent=text;$('.save-flash-bottom',flash).textContent=text;clearTimeout(saveFlashTimer);flash.hidden=false;saveFlashTimer=setTimeout(()=>{flash.hidden=true;},1400);return true;}
function notify(message,error=false){if(!error&&message==='Saved.'&&showSaveFlash(message))return;const n=$("#notice");n.textContent=message;n.className=error?"error":"";n.hidden=false;n.scrollIntoView({block:"nearest",behavior:"smooth"});}
function clearNotice(){const n=$("#notice"),flash=$('#save-flash');if(n)n.hidden=true;if(flash)flash.hidden=true;clearTimeout(saveFlashTimer);}
async function api(route,input={},legacy=false){const r=await fetch("v2/"+(legacy?"":"production-")+route,{method:"POST",headers:{"Content-Type":"application/json","X-ARR-Request":"1"},body:JSON.stringify(input)});const result=await r.json();if(!r.ok)throw new Error(result.error||"Could not complete that action.");return result;}
async function run(fn){if(S.busy)return;S.busy=true;try{clearNotice();await fn();}catch(e){notify(e.message||"Something went wrong. Please try again.",true);}finally{S.busy=false;}}
function bind(id,fn,root=document){const el=$(id,root);if(el)el.onclick=()=>run(fn);}
function opts(items,value){return items.map(i=>{const v=typeof i==="string"?i:(i.id??i.value??i.name);const n=typeof i==="string"?i:(i.label??i.name??i.title??i.id);return `<option value="${esc(v)}" ${String(v)===String(value)?"selected":""}>${esc(n)}</option>`;}).join("");}
function configList(key,fallback){const v=S.catalog?.config?.[key];return Array.isArray(v)&&v.length?v:fallback;}
function field(name,title,{type="text",required=false,help="",values=null,placeholder="",min="",max=""}={}){const value=S.draft?.data[name]??"";let input;if(values)input=`<select name="${esc(name)}" ${required?"required":""}>${opts(values,value)}</select>`;else if(type==="textarea")input=`<textarea name="${esc(name)}" maxlength="2000" ${required?"required":""} placeholder="${esc(placeholder)}">${esc(value)}</textarea>`;else input=`<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${required?"required":""} ${min!==""?`min="${min}"`:""} ${max!==""?`max="${max}"`:""} ${type==="number"?'step="1"':''} maxlength="500" placeholder="${esc(placeholder)}">`;return `<label class="field">${esc(title)}${required?' <span aria-label="required">*</span>':""}${input}${help?`<small>${esc(help)}</small>`:""}</label>`;}
function range(name,title,anchors=false){const v=S.draft?.data[name]??5;return `<label class="field"><span class="range-label"><span>${esc(title)}</span><output class="range-value" for="range-${name}">${esc(v)}</output></span><input id="range-${name}" name="${name}" type="range" min="1" max="10" step="0.5" value="${esc(v)}"><span class="range-anchors"><span>${anchors?faceIcon('sad')+' ':''}1 · Low</span><span>${anchors?faceIcon('neutral')+' ':''}5 · In between</span><span>${anchors?faceIcon('happy')+' ':''}10 · High</span></span></label>`;}
function checks(name,title,choices){const values=S.draft?.data[name]||[];return `<fieldset><legend>${esc(title)}</legend><div class="check-group">${choices.map(v=>`<label><input type="checkbox" name="${esc(name)}" value="${esc(v)}" ${values.includes(v)?"checked":""}>${esc(v)}</label>`).join("")}</div></fieldset>`;}
function collect(form){const d={...S.draft.data};for(const el of form.elements){if(!el.name||el.type==="submit"||el.type==="button")continue;if(el.type==="checkbox"){d[el.name]=$$(`[name="${el.name}"]:checked`,form).map(x=>x.value);}else if(el.type==="range"||el.type==="number"){d[el.name]=el.value===""?"":Number(el.value);}else if(el.name==="safetyConcern"||el.name==="qualityConcern")d[el.name]=el.value==="true";else d[el.name]=el.value;}S.draft.data=d;return d;}
function hasUnsaved(){return Boolean(S.draft&&S.draft.touched);}
function allowLeave(){return !hasUnsaved()||confirm("You have an unfinished entry. Leave without submitting it?");}
window.addEventListener("beforeunload",e=>{if(hasUnsaved()){e.preventDefault();e.returnValue="";}});
function identity(){const area=$("#identity");if(!S.user){area.innerHTML='<span class="pill">Production demo · Alpha</span>';return;}area.innerHTML=`<span><strong>${esc(associateLabel(S.user))}</strong><br><small>${esc(S.user.role==="operator"?`${S.user.username} · Mfg. Associate`:S.user.role==="owner"?"Owner A+":S.user.role==="reviewer"?"Lead / Reviewer":S.user.role)}</small></span><button id="signout" class="small">Sign out</button>`;bind("#signout",async()=>{if(!allowLeave())return;if(S.selected&&!await closeEntry())return;await api("logout");await api("logout",{},true);S.user=null;S.draft=null;S.selected=null;showLogin();identity();});}
function showLogin(){stopStationScanner();S.user=null;identity();const requestedUsername=requestedAssociateUsername();main.innerHTML=`<section class="hero"><div><p class="eyebrow">Better work starts with listening</p><h1>Your experience.<br>Our next improvement.</h1><p class="lead muted">A short check-in connects the people doing the work with the people who can help make it safer, clearer and easier.</p><div class="intro-tiles"><div class="intro-tile"><h3>Share your shift</h3><p>Quick, thoughtful check-ins. Quality and safety always come first.</p></div><div class="intro-tile"><h3>Suggest a better way</h3><p>Turn a practical improvement into a proposal that can be followed through.</p></div><div class="intro-tile"><h3>See what changes</h3><p>Your ideas stay connected to updates and next steps.</p></div></div></div><section class="card login-card"><p class="eyebrow">Explore the demonstration</p><h2>Welcome back</h2><div class="segmented" role="group" aria-label="Sign-in type"><button id="operator-mode" class="${S.loginMode==="operator"?"active":""}">Mfg. Associate</button><button id="staff-mode" class="${S.loginMode==="staff"?"active":""}">Staff workspace</button></div><form id="login-form"><p id="login-error" role="alert"></p><label class="field">${S.loginMode==="operator"?"Fictional Mfg. Associate alias or email":"Username or email"}<input name="username" autocomplete="username" required ${S.loginMode==="operator"?`value="${esc(requestedUsername)}"`:""}></label><label class="field">Password<span class="password-wrap"><input name="password" type="password" autocomplete="current-password" required ${S.loginMode==="operator"&&requestedUsername!=="person-1"?"autofocus":""}><button type="button" id="eye" class="quiet" aria-label="Show password">Show</button></span></label><button class="primary full" type="submit">Sign in</button></form><p class="muted">${S.loginMode==="operator"?"Use a fictional person-1 through person-30 alias or its demo.com email address. Ask your presenter for demo access. Please enter fictional information only.":"Use your existing personal staff account. Access is restricted by role and assigned scope."}</p></section></section>`;bind("#operator-mode",()=>{S.loginMode="operator";showLogin();});bind("#staff-mode",()=>{S.loginMode="staff";showLogin();});$("#eye").onclick=()=>{const p=$("[name=password]");p.type=p.type==="password"?"text":"password";$("#eye").textContent=p.type==="password"?"Show":"Hide";$("#eye").setAttribute("aria-label",p.type==="password"?"Show password":"Hide password");};$("#login-form").onsubmit=e=>{e.preventDefault();run(async()=>{const data=Object.fromEntries(new FormData(e.target));try{if(badgeRequested()){
 const entered=String(data.username).trim().toLowerCase();const result=await api("login",data);if(![result.user?.username,result.user?.profile?.email.toLowerCase()].includes(entered))throw Error('Account confirmation failed. Please try again.');await api("logout",{},true);clearBadgeRequest();
 }else if(S.loginMode==="staff"){await api("logout");await api("login",data,true);}else{await api("logout",{},true);await api("login",data);}await loadSession();}catch(error){$('#login-error').textContent=error.message||'Sign-in failed. Try again.';throw error;}});};if(badgeRequested())badgeConfirmation();}
async function loadSession(){if(badgeRequested()){S.loginMode="operator";S.draft=null;S.selected=null;showLogin();return;}S.catalog=await api("catalog");S.user=S.catalog.user;if(!S.user){showLogin();return;}X.products=(await api('product-list')).products||S.catalog.products||[];S.filters=defaultFilters();S.tab="shifts";identity();await render();}
function legacyShell(){identity();const tabs=isOperator()?[["arr","ARR Check-in"],["prr","PRR Proposal"],["mine","My entries & ideas"]]:[["queue","Review queue"],...(!isLead()?[["dashboard","Team insights"]]:[])];main.innerHTML=`<nav class="tabs" aria-label="Workspace">${tabs.map(([id,label])=>`<button data-tab="${id}" class="${S.tab===id?"active":""}" ${S.tab===id?'aria-current="page"':""}>${label}</button>`).join("")}${!isOperator()&&!isLead()?'<a href="workspace.html#staff">Existing administration ↗</a>':""}</nav><div id="panel"></div>`;$$('[data-tab]').forEach(b=>b.onclick=()=>run(async()=>{if(!allowLeave())return;if(S.selected&&!await closeEntry())return;S.draft=null;S.selected=null;S.tab=b.dataset.tab;await render();}));}
async function legacyRender(){shell();if(S.tab==="arr"||S.tab==="prr"){if(!S.draft||S.draft.form!==S.tab){startDraft(S.tab);const saved=await api("draft",{form:S.tab});if(saved.draft?.data&&Object.keys(saved.draft.data).length){S.draft.data={...S.draft.data,...saved.draft.data};S.draft.version=saved.draft.formVersion||S.draft.version;S.draft.resumed=true;}}renderForm();}else if(S.tab==="dashboard")await dashboard();else await queue();}
function startDraft(form){const hour=Number(new Intl.DateTimeFormat("en-US",{timeZone:"America/Los_Angeles",hour:"2-digit",hourCycle:"h23"}).format(new Date()));const date=datePacific();S.page=0;S.draft={form,version:S.catalog?.forms?.find(f=>f.id===form)?.version||"0.1.0",key:crypto.randomUUID(),touched:false,data:{workDate:hour<3?priorDate(date,1):date,shift:hour>=15||hour<3?"swing":"day",stage:STAGES[0],product:(X.products||[]).find(p=>p.active!==false&&p.common)?.name||PRODUCTS[0],team:"Team A",entryType:"bod",helpNeeded:"No",safetyConcern:false,downtimeCategory:"",qualityStatus:"On track",...(form==="prr"?{estimatedCost:"Unsure"}:{})}};}
function contextFields(){return `<div class="two-col">${field("workDate","Work date",{type:"date",required:true,help:"The date your shift began—even when a Swing shift ends after midnight."})}${field("shift","Shift",{values:configList("shifts",[{id:"day",name:"Day · 5:00 AM–3:30 PM"},{id:"swing",name:"Swing · 3:00 PM–2:00 AM"}]),required:true})}${field("stage","Production stage / station",{values:configList("stages",STAGES),required:true})}${productFields(S.draft?.data?.product||'')}${field("team","Team / work group",{values:configList("teams",["Team A","Team B","Team C"]),required:true})}</div>`;}
function recognition(){const people=S.catalog?.operators||[];return `<h3>A helpful action worth noticing <span class="pill">Optional</span></h3><p class="muted">Did someone help make your work easier, clearer, or safer today?</p>${field("recognition","If you’d like, describe what they did.",{type:"textarea",help:"Read by your scoped Manager, Owner A+, and individually authorized Admins—not coworkers or leads. There are no scores or rankings."})}<label class="field">Who helped? <small>Optional. Select up to two fictional teammates.</small><select name="recognitionPeople" multiple size="3">${people.filter(p=>p.username!==S.user.username).map(p=>`<option value="${esc(p.username)}" ${(S.draft.data.recognitionPeople||[]).includes(p.username)?"selected":""}>${esc(associateLabel(p))}</option>`).join("")}</select></label>`;}
function bodFields(){return `${range("mood","How is your workday looking as you get started?",true)}${range("readiness","How ready do you feel for today’s assignment?")}${range("sopClarity","How clear are the SOP and quality expectations?")}${range("resources","Do you have the tools, materials and information you need?")}${field("helpNeeded","Would training, clarification or teammate assistance help?",{values:["No","Maybe","Yes"]})}${field("helpDetail","What would help? (optional)",{type:"textarea"})}${field("safetyConcern","Any immediate quality or safety concern before starting?",{values:[{id:"false",name:"No"},{id:"true",name:"Yes"}]})}<div id="safety-detail">${field("concernDetail","Brief work-related concern",{type:"textarea",required:S.draft.data.safetyConcern===true,help:"Use required stop-work or escalation procedures for urgent concerns. This form does not replace them."})}</div>${field("note","Anything else about the work ahead? (optional)",{type:"textarea",help:"You don’t need to share personal or medical details."})}`;}
function workFields(changeover=false){return `${changeover?`<div class="two-col">${field("segmentStart","Approximate segment start",{type:"time"})}${field("segmentEnd","Approximate segment end",{type:"time"})}</div>${field("qualityStatus","Quality and safety status",{values:["On track","Concern resolved","Follow-up needed"]})}`:range("experience","How did your shift go overall?",true)}${range("quality","How confident are you in the quality of the work?")}${range("safety","How safe did the work feel?")}${range("sopClarity","How clear were the SOP and quality expectations?")}${!changeover?range("workload","How achievable was the workload?")+range("teamSupport","How supported did you feel by your team?")+range("pride","How satisfied are you with workmanship and organization?"):""}<div class="two-col">${field("safetyConcern","Any safety concern needing follow-up?",{values:[{id:"false",name:"No"},{id:"true",name:"Yes"}]})}${field("qualityConcern","Any quality concern needing follow-up?",{values:[{id:"false",name:"No"},{id:"true",name:"Yes"}]})}</div><div id="safety-detail">${field("concernDetail","Brief work-related concern",{type:"textarea",required:S.draft.data.safetyConcern===true||S.draft.data.qualityConcern===true,help:"Follow required stop-work or escalation procedures for urgent concerns. This check-in is not a replacement."})}</div><div class="callout">Counts are optional. Quality and safety are the priority—not individual quotas or rankings.</div>${field("units","Approximate units processed (optional)",{type:"number",min:0,max:100000,help:"Your own estimate, not an individually measured production total."})}<div class="two-col">${field("downtimeCategory","Any interruption or downtime?",{values:[{id:"",name:"None"},...configList("interruptionCategories",["equipment","material","SOP/clarification","training/help","quality hold","planned changeover","facility interruption","staffing","other"])]})}${field("interruptionMinutes","Approximate minutes (optional)",{type:"number",min:0,max:1440})}</div>${checks("challenges","Anything that made the work harder? (optional)",["Quality","Safety","Ergonomics","Lighting / small print","Lifting / reach","Assembly / orientation","Tool access","SOP clarity"])}${field("workedWell","What worked especially well? (optional)",{type:"textarea"})}${field("improvement","What would make the work safer, clearer or easier next time? (optional)",{type:"textarea"})}${recognition()}${changeover?`<h3>Next assignment</h3><div class="two-col">${field("newStage","Next stage / station",{values:configList("stages",STAGES),required:true})}${productFields(S.draft?.data?.newProduct||'',{name:'newProduct',title:'Next product family'})}</div>`:""}`;}
function proposalFields(){return `${checks("categories","What kind of improvement are you suggesting?",CATEGORIES)}${field("proposal","In two or three sentences, what would you change?",{type:"textarea",required:true})}${field("estimatedCost","What might it cost to try?",{help:"An estimate or “Unsure” is fine. Others can help assess costs."})}${field("expectedValue","What value could this bring?",{type:"textarea",help:"For example: quality, safety, time, waste, ergonomics, training or morale."})}${field("expectedResult","What result would you hope to see?",{type:"textarea",required:true})}${field("supporters","Have others shared a similar idea? (optional)",{type:"textarea",help:"Describe your understanding; this is not treated as anyone else’s consent."})}`;}
function readable(k,v){if(Array.isArray(v)){if(k==="recognitionPeople")return v.map(associateLabelById).join(", ");return v.join(", ");}if(k==="entryType")return entryTypeLabel(v);if(typeof v==="boolean")return v?"Yes":"No";if(typeof v==="object"&&v!==null)return JSON.stringify(v);return String(v??"");}
function summaryData(data){return Object.entries(data).filter(([,v])=>v!==""&&v!==undefined&&v!==null&&(!Array.isArray(v)||v.length)).map(([k,v])=>`<div class="compact-summary"><span class="muted">${esc(labels[k]||k)}</span><span>${esc(readable(k,v))}</span></div>`).join("");}
function renderForm(){const isARR=S.draft.form==="arr";const stepNames=["Your work context",isARR?"Your check-in":"Your idea","Review & submit"];const title=isARR?"A moment to reflect.":"A better way starts here.";$("#panel").innerHTML=`<div class="form-shell"><div class="page-heading"><div><p class="eyebrow">${isARR?"Achievement Recognition Review":"Production Request Review"}</p><h1>${title}</h1><p class="muted">${isARR?"Small observations can make a meaningful difference.":"Share a practical improvement. We’ll keep you connected to the next steps."}</p></div><span class="pill">${isARR?"ARR":"PRR"} · ${esc(S.draft.version)}</span></div><div class="form-head"><p>${isARR?"About 1 minute at the start of a shift · About 3 minutes at the end":"A few clear sentences are enough to begin. No perfect proposal required."}</p></div><ol class="steps">${stepNames.map((name,i)=>`<li class="${S.page===i?"active":""}" ${S.page===i?'aria-current="step"':""}>${i+1}. ${name}</li>`).join("")}</ol>${S.draft.resumed?'<div class="notice-line">Your saved draft has been restored. Review it before submitting.</div>':""}<section class="card"><form id="entry-form"><fieldset><legend>${esc(stepNames[S.page])}</legend>${S.page===0?`${isARR?field("entryType","When are you checking in?",{values:[{id:"bod",name:"Beginning of shift"},{id:"changeover",name:"Product / station changeover"},{id:"eod",name:"End of shift"}],required:true}):""}${contextFields()}`:S.page===1?(isARR?(S.draft.data.entryType==="bod"?bodFields():workFields(S.draft.data.entryType==="changeover")):proposalFields()):`<div class="callout">Please check your entry. Once submitted, your original answers are preserved. Staff follow-up is recorded separately.</div>${summaryData(S.draft.data)}`}</fieldset><div class="actions spread"><button type="button" id="back" ${S.page===0?'disabled':""}>← Back</button><button type="button" id="save-draft">Save draft</button><button class="primary" type="submit">${S.page===2?"Submit "+(isARR?"check-in":"proposal"):"Continue →"}</button></div></form></section><p class="muted">* Required · Fictional information only. Use Save draft to return later. Unsaved changes remain only in this browser tab.</p></div>`;const form=$("#entry-form");form.addEventListener("input",e=>{S.draft.touched=true;if(e.target.type==="range"){const output=$(`[for="${e.target.id}"]`);if(output)output.textContent=e.target.value;}if(e.target.name==="safetyConcern"||e.target.name==="qualityConcern")updateSafety();});function updateSafety(){const yes=$("[name=safetyConcern]")?.value==="true"||$("[name=qualityConcern]")?.value==="true";const box=$("#safety-detail");if(box){box.hidden=!yes;$("[name=concernDetail]").required=yes;}}updateSafety();function save(){collect(form);if(S.draft.data.downtimeCategory!==undefined)S.draft.data.interruptions=S.draft.data.downtimeCategory?[S.draft.data.downtimeCategory]:[];const multi=$("[name=recognitionPeople]",form);if(multi)S.draft.data.recognitionPeople=[...multi.selectedOptions].map(o=>o.value);}bind("#save-draft",async()=>{save();await api("draft",{form:S.draft.form,data:S.draft.data});S.draft.touched=false;notify("Draft saved to your fictional Mfg. Associate account. It has not been submitted.");});bind("#back",()=>{save();S.page--;renderForm();});form.onsubmit=e=>{e.preventDefault();run(async()=>{save();if((S.draft.data.recognitionPeople||[]).length>2)throw new Error("Please choose no more than two teammates.");if(S.page<2){S.page++;renderForm();main.scrollIntoView({block:"start",behavior:"smooth"});return;}const result=await api("submit",{form:S.draft.form,idempotencyKey:S.draft.key,formVersion:S.draft.version,data:S.draft.data,...(S.draft.relatedId?{relatedId:S.draft.relatedId}:{}),...(S.draft.sourceEntryId?{sourceEntryId:S.draft.sourceEntryId}:{})});const entry=result.entry;S.draft=null;$("#panel").innerHTML=`<section class="card confirmation"><span class="success-mark" aria-hidden="true">✓</span><p class="eyebrow">Your perspective matters</p><h1>Thank you for sharing.</h1><p class="muted">${isARR?"Your check-in has been recorded. Your observations help the team understand what supports good work.":"Your proposal is now with management for review. You can follow updates and add comments from My entries & ideas."}</p><p><span class="pill">${esc(entry?.reference||entry?.id||"Submitted")}</span></p><div class="actions"><button id="view-own" class="primary">My entries & ideas</button><button id="new-entry">Another check-in</button></div></section>`;bind("#view-own",async()=>{S.tab="mine";await render();});bind("#new-entry",()=>{S.tab="shifts";return render();});});};}
function reviewState(e){return e.review||e.reviewState||{};}
