async function applyImmediateQueueFilter(form,name){const input=$(`[name="${name}"]`,form);if(!input)return;if(S.selected&&!await closeEntry()){if(input.type==='checkbox')input.checked=!!S.filters[name];else input.value=S.filters[name]||'';return;}S.filters={...S.filters,[name]:input.type==='checkbox'?input.checked:input.value};if(name==='hideReviewed')localStorage.setItem("production-hide-reviewed:"+S.user.id,String(S.filters.hideReviewed));S.selected=null;await loadQueue();}
async function queue(){const panel=$("#panel");panel.innerHTML=`<div class="page-heading"><div><p class="eyebrow">${isOperator()?"Your contributions":"Staff workspace"}</p><h1>${isOperator()?"My entries & ideas":isLead()?"Requested input":"Listen. Understand. Follow through."}</h1><p class="muted">${isOperator()?"Your original entries and management’s shared updates, in one place.":isLead()?"Only items a Manager has explicitly shared with you appear here.":"Review check-ins and improvement ideas. Lead input is optional; Managers own decisions."}</p></div><span class="pill">Pacific work dates</span></div>${queueFilters()}<div id="queue-list" class="queue"><div class="loading">Loading your permitted entries…</div></div>`;const form=$("#filters");for(const name of ['from','to'])$(`[name="${name}"]`,form).addEventListener('change',()=>{$('#queue-filter-pending').hidden=false;});for(const name of ['form','dataSource','hideReviewed','hideCompleted'])$(`[name="${name}"]`,form)?.addEventListener('change',()=>run(()=>applyImmediateQueueFilter(form,name)));form.onsubmit=e=>{e.preventDefault();run(async()=>{const data=Object.fromEntries(new FormData(e.target));if(S.selected&&!await closeEntry())return;S.filters={...S.filters,from:data.from,to:data.to};S.selected=null;await loadQueue();});};bind("#reset-dates",async()=>{if(S.selected&&!await closeEntry())return;const dates=defaultFilters();S.filters={...S.filters,from:dates.from,to:dates.to};S.selected=null;await queue();});await loadQueue();}
