const X={shifts:[],open:null,lastTouchedShift:null,products:[],productHours:{},fgi:null,preview:null,allocation:null,dirty:false};
const uiInput=(name,label,type='text',value='',extra='')=>`<label class="field">${esc(label)}${type==='datetime-local'?' · Pacific time':''}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;
