function shell(){identity();document.body.dataset.form=S.tab==='prr'?'prr':'arr';const tabs=isOperator()?[['shifts','My shift'],['shift-history','Shift history'],['prr','PRR · Suggest improvement'],['mine','My entries & ideas']]:[['shifts','Shift queue'],['queue','ARR / PRR items'],...(!isLead()?[['dashboard','Insights']]:[]),...(canManage()?[['fgi','FGI & allocations']]:[]),...(['admin','owner'].includes(S.user?.role)?[['administration','Administration']]:[])];main.innerHTML=`<nav class="tabs" aria-label="Workspace">${tabs.map(([id,label])=>`<button data-tab="${id}" class="${S.tab===id?'active':''}">${label}</button>`).join('')}${!isOperator()?'<a href="workspace.html?production=1&tab=tickets#staff">Website enhancement tickets ↗</a>':''}</nav><div id="panel"></div>`;$$('[data-tab]').forEach(b=>b.onclick=()=>run(async()=>{if(!allowLeave()||(X.dirty&&!confirm('Discard your unsaved changes?')))return;if(S.selected&&!await closeEntry())return;S.draft=null;S.selected=null;X.open=null;X.dirty=false;S.tab=b.dataset.tab;await render();}));}
async function render(){stopStationScanner();shell();if(S.tab==='shifts'||S.tab==='shift-history')return shiftQueue();if(S.tab==='fgi')return fgiPage();if(S.tab==='administration')return adminPage();if(S.tab==='prr'||S.tab==='arr'){if(!S.draft||S.draft.form!==S.tab){startDraft(S.tab);const saved=await api('draft',{form:S.tab});if(saved.draft?.data){S.draft.data={...S.draft.data,...saved.draft.data};S.draft.version=saved.draft.formVersion||S.draft.version;}}renderForm();}else if(S.tab==='dashboard')await dashboard();else await queue();}
const QUANTITY_KEYS = new Set(['units','reportedMoves','rejected','rejects','rework','lot','downtimeMinutes','interruptionMinutes','countType','unit']);
const REFLECTION_KEYS=new Set(['recognition','recognitionPeople','workedWell']);
const REMOVED_ENTRY_KEYS = new Set(['exception','workException']);
function productFields(value='',{name='productChoice',title='Product / product family'}={}) {
 const list=X.products.length?X.products:PRODUCTS.map(name=>({name,common:true}));
 const names=list.filter(p=>p.active!==false&&p.common!==false&&p.shortList!==false).slice(0,25).map(p=>p.name||p.label||p.family);
 const other=Boolean(value&&!names.includes(value)),searchName=name==='productChoice'?'productOther':name+'Other',listId='product-catalog-'+name;
 return `<div class="product-selector" data-product-name="${esc(name)}">${uiSelect(name,title,[...names,{id:'__other',name:'Other / Find another product…'}],other?'__other':value||names[0])}<label class="field other-product" ${other?'':'hidden'}>Find another product<input name="${esc(searchName)}" list="${esc(listId)}" value="${esc(other?value:'')}" autocomplete="off" ${other?'':'disabled'}><small>Choose a match or type a new name. Unmatched names are reviewed by Admin—not automatically added.</small></label><datalist id="${esc(listId)}">${list.filter(p=>p.active!==false).map(p=>`<option value="${esc(p.name||p.label||p.family)}"></option>`).join('')}</datalist></div>`;
}
function bindProduct(root){$$('[data-product-name]',root).forEach(group=>{const choice=$('select',group),search=$('.other-product input',group);const sync=()=>{const other=choice.value==='__other';$('.other-product',group).hidden=!other;search.disabled=!other;};choice.onchange=()=>{sync();X.dirty=true;if(S.draft)S.draft.touched=true;};sync();});}
function readProduct(root,name='productChoice'){const choice=$(`[name="${CSS.escape(name)}"]`,root);if(!choice)return undefined;const searchName=name==='productChoice'?'productOther':name+'Other';return choice.value==='__other'?($(`[name="${CSS.escape(searchName)}"]`,root)?.value||'').trim():choice.value;}
function stationQrFields(transition=false){const support=stationQrSupport();if(transition)return support;return `<section class="station-qr-launch" aria-labelledby="station-qr-heading"><div class="station-qr-copy"><h3 id="station-qr-heading">At your station?</h3><p>Scan the station QR code to fill Stage / station and Product / product family.</p></div>${stationQrControls()}</section>${support}`;}
function stationQrControls(transition=false){return `<span class="station-qr-actions ${transition?'assignment-scan-actions':''}"><span class="station-qr-icon" aria-hidden="true"><svg viewBox="0 0 64 64" focusable="false"><path d="M5 21V9a4 4 0 0 1 4-4h12M43 5h12a4 4 0 0 1 4 4v12M59 43v12a4 4 0 0 1-4 4H43M21 59H9a4 4 0 0 1-4-4V43" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round"/><path d="M14 15h14v14H14zm4 4v6h6v-6zm18-4h14v14H36zm4 4v6h6v-6zM14 36h14v14H14zm4 4v6h6v-6z" fill="currentColor" fill-rule="evenodd"/><path d="M35 35h5v5h-5zm8 0h7v5h-7zm-8 8h5v7h-5zm8 0h3v3h-3zm5 5h4v4h-4z" fill="currentColor"/><path class="station-scan-line" d="M9 32h46" fill="none" stroke="#df4254" stroke-width="3" stroke-linecap="round"/></svg></span>${transition?'<button type="button" id="access-station-qr" class="primary station-qr-button" aria-label="Open QR reader for station selection">QR reader</button>':'<button type="button" id="access-station-qr" class="primary station-qr-button" aria-label="Open QR reader for station selection">Access station QR reader</button>'}</span>`;}
function stationQrSupport(){return `<p id="station-qr-result" role="status" aria-live="polite"></p><dialog id="station-scan-panel" class="station-scan-panel" aria-labelledby="station-scan-title"><header><h2 id="station-scan-title">Scan station QR</h2><button type="button" id="cancel-station-scan">Cancel scanner</button></header><div class="station-camera-view"><video id="station-scan-video" playsinline muted aria-label="Station QR camera preview"></video><div class="station-aim" aria-hidden="true"></div><p class="station-scan-success" hidden role="status"></p></div><canvas id="station-scan-canvas" hidden></canvas><p id="station-scan-status" role="status" aria-live="polite">Requesting camera access…</p><p class="station-camera-help">Center one QR in the guide. Keep the whole code and its white border visible; move the phone slowly closer or farther away. Codes can also be read outside the guide.</p></dialog>`;}
function stopStationScanner(){const scanner=X.stationScanner;if(!scanner)return;scanner.active=false;clearTimeout(scanner.successTimer);scanner.resize?.disconnect();if(scanner.frame)cancelAnimationFrame(scanner.frame);for(const track of scanner.stream?.getTracks?.()||[])track.stop();scanner.video.srcObject=null;if(scanner.panel.open)scanner.panel.close();X.stationScanner=null;}
window.addEventListener('pagehide',stopStationScanner);
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopStationScanner();});
function setStationProduct(form,product){const choice=$('[name=productChoice]',form),other=$('[name=productOther]',form),group=choice?.closest('[data-product-name]');if(!choice||!other||!group)throw Error('Product selector is unavailable.');const exact=[...choice.options].find(option=>option.value===product);choice.value=exact?product:'__other';const usingOther=choice.value==='__other';$('.other-product',group).hidden=!usingOther;other.disabled=!usingOther;other.value=usingOther?product:'';}
function applyStationQr(form,station){const waiting=$('[name=waitingForAssignment]',form),stage=$('[name=stage]',form),ready=$('[name=readiness][value=ready]',form),actualTime=$('[name=actualTime]',form);if(!waiting||!stage||!ready||!actualTime)throw Error('Begin shift fields are unavailable.');if(![...stage.options].some(option=>option.value===station.stage))throw Error('This station is not available in the current Stage / station list.');waiting.checked=false;const assigned=$('.assigned-fields',form);assigned.hidden=false;assigned.disabled=false;$('.waiting-hint',form).hidden=true;stage.value=station.stage;setStationProduct(form,station.product);ready.checked=Boolean(station.demoReady);form.dataset.demoReadiness=station.demoReady?'true':'false';form.dataset.stationQrId=station.id;X.dirty=true;}
function qrActionTime(form,workDate){
 const input=$('[name=actualTime]',form);
 if(form.dataset.stationQrUsed==='true'&&workDate!==defaultWorkDate()&&form.dataset.qrTimeEdited!=='true')throw Error('Enter the actual historical action time before saving.');
 if(form.dataset.stationQrUsed==='true'&&form.dataset.qrTimeEdited!=='true'&&workDate===defaultWorkDate())return new Date().toISOString();
 return isoStamp(input.value);
}
function markQrTime(form,workDate){
 form.dataset.stationQrUsed='true';
 if(workDate!==defaultWorkDate()&&form.dataset.qrTimeEdited!=='true')$('[name=actualTime]',form).value='';
}
function acceptStationScan(form,station){
 if(form.onStationQr){form.onStationQr(station);return;}
 applyStationQr(form,station);markQrTime(form,$('[name=workDate]',form).value);
 $('#station-scan-demo-note',form).hidden=!station.demoReady;
 $('#station-qr-result',form).textContent=station.stage+' — '+station.product+'. Review the details, then select Begin shift.';
 $('.actions .primary',form)?.focus();
}
function recognizedStationScan(form,station,scanner){
 const success=$('.station-scan-success',scanner.panel),view=scanner.video.parentElement;
 success.textContent='✓ Recognized: '+(station.action==='end'?'End Shift / End of Day':station.stage+' — '+station.product);success.hidden=false;view.classList.add('scan-recognized');
 $('#station-scan-status',form).textContent='Returning to the form for your review. Nothing has been saved.';
 scanner.resize?.disconnect();for(const track of scanner.stream?.getTracks?.()||[])track.stop();scanner.stream=null;scanner.video.srcObject=null;
 scanner.successTimer=setTimeout(()=>{if(!scanner.active||!form.isConnected)return;stopStationScanner();try{acceptStationScan(form,station);}catch(error){notify(error.message||'Could not apply scanned code.',true);}},1200);
}
async function beginStationScanner(form){
 const panel=$('#station-scan-panel',form),video=$('#station-scan-video',form),canvas=$('#station-scan-canvas',form),status=$('#station-scan-status',form);
 if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera access is not supported by this browser.');
 if(!globalThis.ARRStationQR?.parse)throw Error('The station QR reader did not load. Refresh and try again.');
 stopStationScanner();const scanner={active:true,stream:null,panel,video,frame:null};X.stationScanner=scanner;
 $('.station-scan-success',panel).hidden=true;video.parentElement.classList.remove('scan-recognized');panel.showModal();status.textContent='Requesting camera access…';
 const cancel=()=>{stopStationScanner();$('#access-station-qr',form)?.focus();};
 $('#cancel-station-scan',form).onclick=cancel;panel.oncancel=e=>{e.preventDefault();cancel();};panel.onclose=()=>{if(X.stationScanner===scanner)stopStationScanner();};
 try{
  const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});
  if(!scanner.active||!form.isConnected){for(const track of stream.getTracks())track.stop();return;}
  scanner.stream=stream;video.srcObject=stream;await video.play();if(!scanner.active)return;
  status.textContent='Center the QR in the guide. Hold steady.';
  const view=video.parentElement,aim=$('.station-aim',view);
  const resize=()=>{if(!video.videoWidth||!video.videoHeight)return;const scale=Math.min(view.clientWidth/video.videoWidth,view.clientHeight/video.videoHeight);const size=Math.min(video.videoWidth,video.videoHeight)*scale*.72;aim.style.width=aim.style.height=size+'px';};
  scanner.resize=new ResizeObserver(resize);scanner.resize.observe(view);video.onloadedmetadata=resize;resize();
  let detector=null;if(globalThis.BarcodeDetector){try{detector=new BarcodeDetector({formats:['qr_code']});}catch{}}
  const context=canvas.getContext('2d',{willReadFrequently:true});let last=0;
  const detect=async now=>{
   if(!scanner.active)return;if(!form.isConnected){stopStationScanner();return;}
   if(now-last<150){scanner.frame=requestAnimationFrame(detect);return;}last=now;
   try{
    let value='';if(video.readyState>=2&&video.videoWidth&&video.videoHeight){
     if(detector){try{const codes=await detector.detect(video);value=codes[0]?.rawValue||'';}catch{detector=null;}}
     if(!detector&&globalThis.jsQR){const scale=Math.min(1,1280/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);context.drawImage(video,0,0,canvas.width,canvas.height);const image=context.getImageData(0,0,canvas.width,canvas.height);value=globalThis.jsQR(image.data,image.width,image.height,{inversionAttempts:'attemptBoth'})?.data||'';}
    }
    if(!scanner.active||!form.isConnected)return;
    if(value){const station=globalThis.ARRStationQR.parse(value);if(!station){status.textContent='Unrecognized station QR. Use one of the registered ARR codes.';}else if(station.action==='end'&&!form.onStationQr){status.textContent='End Shift QR is for an active shift. Cancel this scanner and open your current shift.';}else{recognizedStationScan(form,station,scanner);return;}}
   }catch{if(scanner.active)status.textContent='Unable to read this frame. Hold steady or move the phone slightly.';}
   if(scanner.active)scanner.frame=requestAnimationFrame(detect);
  };scanner.frame=requestAnimationFrame(detect);
 }catch(error){if(!scanner.active)return;stopStationScanner();throw Error(error.name==='NotAllowedError'?'Camera permission was denied. Allow camera access for this site, or use the manual station fields.':'Camera could not start. Try again or use the manual station fields.');}
}
function bindStationScanner(form){const button=$('#access-station-qr',form);if(button)button.onclick=event=>{event.preventDefault();event.stopPropagation();run(()=>beginStationScanner(form));};$('[name=actualTime]',form)?.addEventListener('input',()=>{form.dataset.qrTimeEdited='true';});}

function assignment(form){if($('[name=waitingForAssignment]',form)?.checked)return null;const d=Object.fromEntries(new FormData(form)),product=readProduct(form);if(!product)throw Error('Select or enter a product.');const found=X.products.find(p=>(p.name||p.label||p.family)===product);return {stage:d.stage,station:d.station||d.stage,product,...(found?.id?{productId:found.id}:{})};}
function optionalWork(){return `<section class="feedback-quantity-fields"><h4>Quantities &amp; lot details <span class="pill">Optional</span></h4><div class="two-col">${uiInput('reportedMoves','Gate Passes','number','','min="0" step="1"')}${uiInput('rejected','Gate Holds','number','','min="0" step="1"')}${uiInput('rework','Rework observed','number','','min="0" step="1"')}${uiInput('lot','Lot / batch reference')}${uiInput('interruptionMinutes','Downtime minutes','number','','min="0"')}</div><button type="button" id="save-feedback-gate-quantities" class="small">Save gate quantities</button><small id="feedback-gate-status" role="status"></small><small>Quality and safety come first. Gate quantities are station-level operational counts, not finished-goods totals. Blank means not counted, not zero.</small></section>`;}
function segmentExtras(form){const d=Object.fromEntries(new FormData(form)),extras={};for(const key of ['rejected','rework','interruptionMinutes'])if(d[key]!==undefined&&d[key]!=='')extras[key]=Number(d[key]);if(d.lot?.trim())extras.lot=d.lot.trim();extras.countType=d.reportedMoves===''?'not_counted':'estimated';return extras;}
function faceIcon(mood){const mouth=mood==='sad'?'M9 23 Q16 16 23 23':mood==='happy'?'M9 20 Q16 27 23 20':'M9 22 H23';return `<svg class="face-icon" viewBox="0 0 32 32" width="32" height="32" aria-hidden="true" focusable="false"><circle cx="16" cy="16" r="14" fill="#ffda55" stroke="#b88005" stroke-width="1.2"/><circle cx="11" cy="12" r="1.5" fill="#4f3d11"/><circle cx="21" cy="12" r="1.5" fill="#4f3d11"/><path d="${mouth}" fill="none" stroke="#4f3d11" stroke-width="2" stroke-linecap="round"/></svg>`;}
function moodQuestion(name,title,lo='Difficult',hi='Very good'){return `<label class="field"><span>${esc(title)}</span><span class="range-label"><small>Choose a response (optional)</small><output>Not answered</output></span><input type="range" data-optional-range name="${name}" min="1" max="10" step="0.5" value="5" disabled><button type="button" class="small answer-range">Answer</button><span class="range-anchors"><span>${faceIcon('sad')} ${esc(lo)}</span><span>${faceIcon('neutral')} In between</span><span>${faceIcon('happy')} ${esc(hi)}</span></span></label>`;}
function bindRanges(root){$$('.answer-range',root).forEach(b=>b.onclick=()=>{const r=$('input',b.parentElement);r.disabled=false;$('output',b.parentElement).textContent=r.value;b.hidden=true;X.dirty=true;r.focus();});$$('[data-optional-range]',root).forEach(r=>r.oninput=()=>{$('output',r.parentElement).textContent=r.value;X.dirty=true;});}
async function applyImmediateShiftFilter(form,name){const input=$(`[name="${name}"]`,form);if(!input)return;if(X.dirty&&!confirm('Discard unsaved changes and apply this filter?')){if(name==='team')input.value=X.team||'';else input.checked=X.hideClosed!==false;return;}if(name==='team')X.team=input.value||'';else X.hideClosed=input.checked;X.dirty=false;await shiftQueue();}
function productHourLabel(minutes){const total=Math.max(0,Math.round(Number(minutes)||0)),hours=Math.floor(total/60),remainder=total%60;return hours?`${hours}h${remainder?` ${remainder}m`:''}`:`${remainder}m`;}
function associateHoursPreview(operator){const summary=X.productHours?.[operator],items=summary?.items||[];return `<span class="associate-hours-preview hover-preview" role="tooltip" aria-hidden="true"><strong>Net production time by product</strong><small>${esc(X.from||'All dates')} through ${esc(X.to||'All dates')}</small>${items.length?items.map(v=>`<span data-product-hours-row><span>${esc(v.product)}</span><b>${esc(productHourLabel(v.minutes))}</b></span>`).join(''):'<span>No production time in this date range.</span>'}${summary?.hasMore?'<span class="more-products-indicator" aria-label="More products">…</span>':''}</span>`;}
function currentTimelinePreview(segments){return `<span class="current-timeline-preview hover-preview" role="tooltip" aria-hidden="true"><strong>Shift timeline through current</strong>${segments.map((v,i)=>`<span><b>${i+1}. ${esc(v.stage||segmentKindName(v))}</b><small>${esc(v.product||segmentKindName(v))} · ${esc(timeLabel(v.start))} — ${v.end?esc(timeLabel(v.end)):'Now'} · ${esc(segmentKindText(v))}</small></span>`).join('')}</span>`;}
function paintShiftPresence(rows){const target=$('#shift-list');if(!target)return;target.innerHTML=rows.length?rows.map(s=>`<article class="queue-item"><div class="queue-summary shift-summary presence-summary" data-shift="${esc(s.id)}" data-presence-only="true"><span><strong>${esc(associateLabelById(s.operator||s.username))}</strong><small>${esc(s.workDate)} · ${esc(s.shift)} · ${esc(s.team)}</small></span><span class="presence-detail"><small>Loading current work…</small></span><span class="pill">${esc(statusShift(s.status))}</span></div><div id="shift-${esc(s.id)}" hidden></div></article>`).join(''):'<div class="loading">Loading current shifts…</div>';}
function paintShiftRows(rows){
 const target=$('#shift-list');if(!target)return;const manager=canManage(),movable=s=>manager&&s.status==='in_progress'&&/^person-\d+$/.test(s.operator||s.username);
 target.innerHTML=rows.length?rows.map(s=>{const seg=s.segments||[],current=seg.at(-1),previous=seg.at(-2),operator=s.operator||s.username,peers=rows.filter(v=>movable(v)&&v.workDate===s.workDate&&v.shift===s.shift),position=peers.findIndex(v=>v.id===s.id);const line=(v,title)=>v?`<small class="${title==='Current'?`current-segment-row${manager?' current-hover-target':''}`:title==='Previous'?'previous-segment-row':''}"><span class="${title==='Current'?'current-segment-label':''}">${title}</span> ${esc(v.stage)} · · ${esc(v.product)} · · ${esc(timeLabel(v.start))} — ${v.end?esc(timeLabel(v.end)):'Now'}${!v.end?' · · Changed '+esc(age(v.start)):''} · · ${segmentKindLabel(v)}${title==='Current'&&manager?currentTimelinePreview(seg):''}</small>`:'';const summary=`<button class="queue-summary shift-summary${X.lastTouchedShift===s.id?' last-touched-shift':''}" data-shift="${esc(s.id)}" aria-expanded="false"><span${manager?' class="associate-hours-target"':''}><strong>${esc(associateLabelById(operator))}</strong><small>${esc(s.workDate)} · ${esc(s.shift)} · ${esc(s.team)} · Shift total ${shiftTotalDuration(seg)}</small>${manager?associateHoursPreview(operator):''}</span><span>${line(previous,'Previous')}${line(current,current?.end?'Last':'Current')}</span><span class="pill">${esc(statusShift(s.status))}</span></button>`,controls=movable(s)?`<div class="shift-order-controls" aria-label="Order ${esc(associateLabelById(operator))}"><button type="button" data-shift-order="${esc(s.id)}" data-direction="up" aria-label="Move ${esc(associateLabelById(operator))} up one position" ${position<=0?'disabled':''}>↑</button><button type="button" data-shift-order="${esc(s.id)}" data-direction="down" aria-label="Move ${esc(associateLabelById(operator))} down one position" ${position===peers.length-1?'disabled':''}>↓</button></div>`:'';return `<article class="queue-item${manager?' manager-preview-row':''}">${controls?`<div class="shift-row-shell">${summary}${controls}</div>`:summary}${s.canManage&&s.status==='submitted'?`<label class="check select-close"><input type="checkbox" data-close-shift="${esc(s.id)}"> Select for closeout</label>`:''}<div id="shift-${esc(s.id)}" hidden></div></article>`;}).join(''):'<div class="empty">No shifts match this view. Adjust dates or crew filters; no records are deleted.</div>';
 $$('[data-shift]',target).forEach(b=>b.onclick=()=>run(()=>openShift(b.dataset.shift)));$$('[data-shift-order]',target).forEach(button=>button.onclick=event=>{event.stopPropagation();run(()=>moveShiftRow(button.dataset.shiftOrder,button.dataset.direction));});
}
async function moveShiftRow(id,direction){if(X.dirty&&!confirm('Discard unsaved changes and reorder this shift list?'))return;const row=X.shifts.find(v=>v.id===id);if(!row)return;X.dirty=false;const visible=X.shifts.filter(v=>v.status==='in_progress'&&/^person-\d+$/.test(v.operator||v.username)&&v.workDate===row.workDate&&v.shift===row.shift),anchor=queueViewportAnchor(),result=await api('shift-order-move',{workDate:row.workDate,shift:row.shift,operator:row.operator||row.username,direction,visibleOperators:visible.map(v=>v.operator||v.username)}),ordered=new Map(result.orderedOperators.map(operator=>[operator,visible.find(v=>(v.operator||v.username)===operator)]));let cursor=0;X.shifts=X.shifts.map(v=>visible.includes(v)?ordered.get(result.orderedOperators[cursor++])||v:v);X.open=null;paintShiftRows(X.shifts);await restoreQueueViewportAnchor(anchor);const same=$(`[data-shift-order="${CSS.escape(id)}"][data-direction="${CSS.escape(direction)}"]`),summary=$(`[data-shift="${CSS.escape(id)}"]`);if(same&&!same.disabled)same.focus();else summary?.focus();}

function queueViewportAnchor(){const row=$$('[data-shift]').find(node=>{const box=node.getBoundingClientRect();return box.bottom>0&&box.top<innerHeight;});if(!row)return null;return{id:row.dataset.shift,top:row.getBoundingClientRect().top};}
async function restoreQueueViewportAnchor(anchor){if(!anchor)return;const row=$(`[data-shift="${CSS.escape(anchor.id)}"]`);if(!row)return;window.scrollBy({top:row.getBoundingClientRect().top-anchor.top,behavior:'auto'});}
async function shiftQueueAtAnchor(anchor){const root=document.documentElement,prior=root.style.overflowAnchor;root.style.overflowAnchor='none';try{await shiftQueue();await restoreQueueViewportAnchor(anchor);}finally{root.style.overflowAnchor=prior;}}
async function refreshQuickShiftButtons(){const controls=$('#quick-shift-controls');if(!controls)return;controls.hidden=X.hideClosed===false;if(controls.hidden)return;const buttons=$$('[data-quick-shift]',controls);if(!X.to){for(const button of buttons){button.disabled=true;button.title='Apply a Through work date before creating a quick-start preview.';}return;}const status=await api('shift-quick-status',{workDate:X.to});for(const shift of ['day','swing']){const button=$(`[data-quick-shift="${shift}"]`,controls),value=status[shift]||{};button.disabled=!value.enabled;button.title=value.locked?'Another Manager has a preview open.':value.eligible?`${value.eligible} eligible Mfg. Associates${value.skipped?`; ${value.skipped} will be skipped`:''}`:'No eligible prior closed shifts for this work date.';}}
async function cancelQuickShiftPreview(token){if(!token)return;try{await api('shift-quick-cancel',{token});}catch{/* The lock expires automatically after 15 minutes. */}if(X.quickStartToken===token)X.quickStartToken=null;}
