function readinessFields(){return `<fieldset class="assignment-readiness"><legend>SOP readiness · choose before starting</legend><label class="check"><input type="radio" name="readiness" value="ready" required> I understand the instructions and am ready to begin. <span id="station-scan-demo-note" class="station-demo-warning" hidden>(Demo preselected — not an SOP rating)</span></label><label class="check"><input type="radio" name="readiness" value="help" required> I’ll review the SOP or ask for clarification before starting.</label><p class="muted">SOP preparation is training time. A lead or supervisor confirms readiness before production begins.</p></fieldset>`;}
function assignmentFields(stage='',product=''){return `<div class="assignment-choice"><label class="check"><input type="checkbox" name="waitingForAssignment"> Stage / station: Not Determined Yet</label><fieldset class="assigned-fields"><div class="two-col">${uiSelect('stage','Stage / station',STAGES,stage)}${productFields(product)}</div>${readinessFields()}</fieldset><p class="waiting-hint segment-training" hidden>Waiting for assignment is recorded separately, not as production or training time. Change assignment when you know where to go.</p></div>`;}
