async function openShift(id){if(X.dirty&&!confirm('Discard unsaved shift changes?'))return;X.dirty=false;if(X.open){const old=document.getElementById('shift-'+X.open);if(old){await animateDetail(old,false);old.innerHTML='';}const oldButton=$(`[data-shift="${CSS.escape(X.open)}"]`);oldButton?.setAttribute('aria-expanded','false');if(X.open===id){X.open=null;return;}}const out=await api('shift-detail',{id});X.open=id;const el=document.getElementById('shift-'+id);if(!out.shift){await showReadiness(id,out.readiness);return;}await shiftDetails(out.shift,el);$(`[data-shift="${CSS.escape(id)}"]`)?.setAttribute('aria-expanded','true');await animateDetail(el,true);}
