function updateElapsedDurations(){document.querySelectorAll('[data-elapsed-start]').forEach(el=>{el.textContent=segmentDuration(el.dataset.elapsedStart,null);});document.querySelectorAll('[data-shift-elapsed-start]').forEach(el=>{el.textContent=segmentDuration(el.dataset.shiftElapsedStart,null);});}
