async function paintAllocation(){const v=X.preview,p=$('#allocation-preview');p.innerHTML=`<h3>Unsaved preview · ${esc(v.method)}</h3><p>Demo FGI total: ${esc(v.total)}. Training/preparation and waiting-for-assignment minutes are excluded.</p>${(v.issues||[]).map(i=>`<p class="notice-line">${esc(i)}</p>`).join('')}${allocationTable(v,v.method==='adjusted'&&canManage())}${canManage()?'<details><summary>Compare allocation methods</summary><button id="compare-methods">Calculate comparison</button><div id="method-comparison"></div></details>':''}<p class="muted">Reported moves remain unchanged. Estimates are not proof of individual output or accuracy.</p><div class="actions">${v.method==='adjusted'&&canManage()?'<button id="recalculate-adjustments">Preview adjustments</button>':''}${canManage()?`<button id="save-allocation" class="primary" ${v.canSave?'':'disabled'}>Save revised allocation</button>`:''}</div>`;$$('.allocation-adjustment',p).forEach(i=>i.oninput=()=>{$('#save-allocation').disabled=true;X.dirty=true;});bind('#compare-methods',compareAllocationMethods);bind('#recalculate-adjustments',async()=>{const adjustments={};$$('.allocation-adjustment',p).forEach(i=>{if(i.value!=='')adjustments[i.dataset.operator]=Number(i.value);});X.allocationInput={...X.allocationInput,adjustments};X.preview=(await api('allocation-preview',X.allocationInput)).preview;await paintAllocation();});bind('#save-allocation',async()=>{const old=(X.allocations||[]).find(a=>a.id===v.id);await api('allocation-save',{...X.allocationInput,fingerprint:v.fingerprint,revision:old?.revision||0});X.dirty=false;await savedAllocations();notify('Allocation revision saved with source inputs and audit history.');});}
