function refreshAllocationProductSummary(index){const product=X.allocationBoard.products[index],row=$(`[data-allocation-product="${index}"]`),summary=$('.allocation-product-summary',row);summary.outerHTML=allocationProductSummary(product,index);const button=$(`[data-expand-allocation="${index}"]`,row);button.textContent='Collapse';button.onclick=()=>run(()=>expandAllocationProduct(index));}
async function runBusySaveAllocation(family){await run(async()=>{const index=X.allocationBoard.products.findIndex(p=>p.family===family),root=$(`[data-allocation-detail="${index}"]`),preview=X.allocationRuns[family];if(!recountAllocationBalance(root))throw Error('Balance every operation to its adjusted target before saving.');const operations=preview.operations.map((operation,i)=>{const card=$(`[data-operation-index="${i}"]`,root);return{operation:operation.operation,target:operation.target,allocations:$$('[data-allocation-input]',card).map(input=>({operator:input.dataset.operator,allocated:Number(input.value)}))};}),result=await api('allocation-run-save',{from:preview.from,to:preview.to,family,profileOverrides:allocationProfileOverrides(root),fingerprint:preview.fingerprint,revision:preview.revision,operations,adjustmentReason:$('[name=allocationReason]',root).value});preview.revision=result.run.revision;preview.fingerprint=result.run.fingerprint;const product=X.allocationBoard.products[index];product.allocatedOperations=result.run.operations.length;product.remainingOperations=Math.max(0,product.totalOperations-product.allocatedOperations);product.currentRunRevision=result.run.revision;product.stale=false;root.dataset.needsRecalculation='false';clearAllocationDirty(family);refreshAllocationProductSummary(index);notify('Balanced product allocation saved with lag, scrap-rate and Manager-adjustment audit details.');});}
function paintAllocationBoard(out){const root=$('#allocation-board');if(!root)return;X.allocationBoard=out;root.innerHTML=out.products.length?`<div class="allocation-product-list">${out.products.map(allocationProductRow).join('')}</div>`:'<div class="empty">No FGI exists in the selected range.</div>';$$('[data-expand-allocation]',root).forEach(button=>button.onclick=()=>run(()=>expandAllocationProduct(Number(button.dataset.expandAllocation))));}
