fgiPage=async function(){await legacyFgiPage();X.allocationDirty=new Set();X.fgiDirty=false;const fgiForm=$('#fgi-form');fgiForm?.addEventListener('input',()=>{X.fgiDirty=true;X.dirty=true;});const legacyForm=$('#allocation-form')?.closest('section'),legacySaved=$('#saved-allocations')?.closest('section');legacyForm?.remove();legacySaved?.remove();const today=datePacific();X.allocationTo??=today;X.allocationFrom??=priorDate(X.allocationTo,6);const daily=$('#fgi-form')?.closest('section');daily?.insertAdjacentHTML('afterend',`<section class="card allocation-board-card"><div class="actions spread"><div><h2>FGI allocation board</h2><p class="muted">Defaults to seven days. Products are ordered by highest FGI quantity. Expand first, calculate proposed hour-based allocations, review, then save.</p></div></div><form id="allocation-range" class="filters">${uiInput('from','FGI date from','date',X.allocationFrom,'required')}${uiInput('to','Through','date',X.allocationTo,'required')}<button>Apply range</button></form><div id="allocation-board"><div class="loading">Loading allocation board…</div></div><div id="saved-allocations" hidden></div></section>`);const range=$('#allocation-range');range.onsubmit=e=>{e.preventDefault();run(async()=>{if(allocationDirty().size&&!confirm('Discard unsaved allocation drafts and change the FGI range?'))return;const data=new FormData(range),nextFrom=String(data.get('from')),nextTo=String(data.get('to'));if(!nextFrom||!nextTo||nextFrom>nextTo)throw Error('Choose a valid FGI date range.');const out=await api('allocation-board',{from:nextFrom,to:nextTo});allocationDirty().clear();X.dirty=X.fgiDirty===true;X.allocationFrom=nextFrom;X.allocationTo=nextTo;paintAllocationBoard(out);});};await loadAllocationBoard();};

async function adminPage(){const p=$('#panel');p.innerHTML=`<div class="page-heading"><div><p class="eyebrow">Production demonstration administration</p><h1>Keep the tool useful and simple.</h1><p class="muted">Catalog review, multi-staff Production visibility routing and versioned form content. Historical responses keep their original definitions.</p></div></div><section class="card"><h2>Accounts, password resets & website tickets</h2><p>Use the established administration controls in the production-styled workspace.</p><a class="button-link" href="workspace.html?production=1&tab=accounts">Open administration workspace ↗</a></section><section class="card"><details><summary>Station QR validation · 15 registered codes</summary><div id="station-qr-validation"></div></details></section><section class="card"><details><summary>Associate demo-account access</summary><div id="associate-admin"></div></details></section><section class="card"><details><summary>Product catalog · common and long lists</summary><div id="catalog-admin"></div></details></section><section class="card"><details><summary>Crews & readiness routing</summary><div id="crew-admin"></div></details></section><section class="card"><details><summary>Form definitions · Admin draft → A+ publish</summary><div id="form-admin"><div class="actions"><button data-edit-form="arr">Edit ARR</button><button data-edit-form="prr">Edit PRR</button></div><div id="definition-editor"></div></div></details></section>`;stationQrValidation();await Promise.all([catalogAdmin(),crewAdmin(),associateAdmin()]);$$('[data-edit-form]').forEach(b=>b.onclick=()=>run(()=>formAdmin(b.dataset.editForm)));}
async function catalogAdmin(){const out=await api('product-list',{includeInactive:true});X.products=out.products||[];const el=$('#catalog-admin');el.innerHTML=`<form id="product-edit"><div class="two-col">${uiSelect('id','Existing product',[{id:'',name:'Add a new product'},...X.products.map(p=>({id:p.id,name:p.name}))])}${uiInput('name','Product name','text','','required')}</div><label class="check"><input name="common" type="checkbox"> Show in common-product list</label><label class="check"><input name="active" type="checkbox" checked> Active</label>${uiInput('aliases','Alternate names (comma separated)')}<button>Save product</button></form><h3>Unmatched typed entries</h3><p class="muted">Typing does not automatically expand the catalog. Map spelling variants to an existing product or add a genuinely new one.</p>${(out.unmatched||[]).map((u,i)=>`<form class="resolve-product" data-index="${i}"><strong>${esc(u.name||u.product||u.text)}</strong>${uiSelect('productId','Map to existing',[{id:'',name:'Add as a new product'},...X.products.map(p=>({id:p.id,name:p.name}))])}${uiInput('name','Name if adding new','text',u.name||u.product||u.text||'')}<button>Resolve entry</button></form>`).join('')||'<p>No unmatched products awaiting review.</p>'}`;const form=$('#product-edit');$('[name=id]',form).onchange=()=>{const v=X.products.find(p=>p.id===$('[name=id]',form).value);$('[name=name]',form).value=v?.name||'';$('[name=common]',form).checked=!!v?.common;$('[name=active]',form).checked=v?.active!==false;$('[name=aliases]',form).value=(v?.aliases||[]).join(', ');};form.onsubmit=e=>{e.preventDefault();run(async()=>{const d=Object.fromEntries(new FormData(form));const old=X.products.find(p=>p.id===d.id);await api('product-save',{...d,revision:old?.revision||0,common:d.common==='on',active:d.active==='on',aliases:d.aliases.split(',').map(s=>s.trim()).filter(Boolean)});await catalogAdmin();notify('Catalog updated. Original entered wording is preserved.');});};$$('.resolve-product',el).forEach(f=>f.onsubmit=e=>{e.preventDefault();run(async()=>{const d=Object.fromEntries(new FormData(f)),u=out.unmatched[Number(f.dataset.index)];await api('product-resolve',{id:u.id,...(d.productId?{productId:d.productId}:{name:d.name})});await catalogAdmin();notify('Unmatched product resolved. Affected allocations require refresh.');});});}
function multiStaffControl(name,label,people,selected,user){const chosen=new Set(selected||[]);return `<details class="staff-multi" data-staff-multi="${esc(name)}" data-staff-user="${esc(user)}" data-staff-label="${esc(label)}"><summary><span data-selected-count>${chosen.size?chosen.size+' selected':'Unassigned'}</span></summary><div class="staff-multi-options">${people.map(person=>`<label class="check"><input type="checkbox" name="${esc(name)}" value="${esc(person.id)}" aria-label="${esc(person.username+' · '+label+' for '+user)}" ${chosen.has(person.id)?'checked':''}> ${esc(person.username)}</label>`).join('')||'<span class="muted">No eligible staff</span>'}</div></details>`;}
