async function crewAdmin(){const out=await api('settings-get');const settings=out.settings||{};const staff=out.staff||[],supervisors=staff.filter(s=>s.role==='manager'&&(s.forms||[]).includes('arr')),leads=staff.filter(s=>['lead','reviewer'].includes(s.role)&&(s.forms||[]).includes('arr'));const el=$('#crew-admin');el.innerHTML=`<p class="muted">Supervisor and Lead assignments control Production-shift visibility for all current and historical shifts. ARR/PRR sharing remains unchanged. Assigned Supervisors may correct shifts; assigned Leads are read-only and may confirm SOP readiness.</p><form id="crew-form">${uiInput('teams','Crew names (comma separated)','text',(settings.teams||['Team A','Team B','Team C']).join(', '))}<div class="crew-bulk"><fieldset><legend>Supervisor bulk assignment</legend>${uiSelect('bulkManager','Supervisor',[{id:'',name:'Choose Supervisor'},...supervisors.map(s=>({id:s.id,name:s.username}))])}<div class="actions"><button type="button" data-bulk-staff="managerIds" data-bulk-mode="select">Select all associates</button><button type="button" data-bulk-staff="managerIds" data-bulk-mode="clear">Clear all associates</button></div></fieldset><fieldset><legend>Lead bulk assignment</legend>${uiSelect('bulkLead','Lead',[{id:'',name:'Choose Lead'},...leads.map(s=>({id:s.id,name:s.username}))])}<div class="actions"><button type="button" data-bulk-staff="leadIds" data-bulk-mode="select">Select all associates</button><button type="button" data-bulk-staff="leadIds" data-bulk-mode="clear">Clear all associates</button></div></fieldset></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Associate</th><th>Crew</th><th>Default shift</th><th>Supervisor</th><th>Lead</th></tr></thead><tbody>${(S.catalog.operators||[]).map(o=>{const user=o.username,a=settings.crewAssignments?.[user]||{};return `<tr data-crew-user="${esc(user)}"><td>${esc(associateLabel(o))}</td><td><input name="team" aria-label="${esc(user)} crew" value="${esc(a.team||'')}"></td><td><select name="defaultShift" aria-label="${esc(user)} default shift">${opts([{id:'day',name:'Day'},{id:'swing',name:'Swing'}],a.defaultShift||'day')}</select></td><td>${multiStaffControl('managerIds','Supervisors',supervisors,a.managerIds,user)}</td><td>${multiStaffControl('leadIds','Leads',leads,a.leadIds,user)}</td></tr>`;}).join('')}</tbody></table></div><button>Save crew and visibility assignments</button></form>${S.user.role==='owner'?`<details><summary>Individual administrative and operational grants</summary><p>A+ visibility alone does not permit operational correction or approval. Grant Manager authority explicitly when appropriate.</p><form id="permission-form">${uiSelect('userId','Staff account',staff.map(s=>({id:s.id,name:s.username+' · '+s.role})))}<label class="check"><input name="operationalManager" type="checkbox"> Additional Manager / Supervisor authority</label><label class="check"><input name="recognition" type="checkbox"> Allow this Admin to read restricted recognition</label><label class="check"><input name="updates" type="checkbox"> Allow this Admin to publish worker-visible proposal updates</label><button>Save individual permissions</button></form></details>`:''}`;refreshStaffMulti(el);$$('[data-staff-multi] input',el).forEach(input=>input.onchange=()=>refreshStaffMulti(el));$$('[data-bulk-staff]',el).forEach(button=>button.onclick=()=>{const field=button.dataset.bulkStaff,selectName=field==='managerIds'?'bulkManager':'bulkLead',staffId=$(`[name=${selectName}]`,el).value;if(!staffId){notify('Choose a '+(field==='managerIds'?'Supervisor':'Lead')+' first.');return;}$$(`[data-crew-user] [name=${field}][value="${CSS.escape(staffId)}"]`,el).forEach(input=>input.checked=button.dataset.bulkMode==='select');refreshStaffMulti(el);});$('#crew-form').onsubmit=e=>{e.preventDefault();run(async()=>{const crewAssignments={};$$('[data-crew-user]',el).forEach(row=>{if(!$('[name=team]',row).value.trim())return;crewAssignments[row.dataset.crewUser]={team:$('[name=team]',row).value.trim(),defaultShift:$('[name=defaultShift]',row).value,managerIds:$$('[name=managerIds]:checked',row).map(input=>input.value),leadIds:$$('[name=leadIds]:checked',row).map(input=>input.value)};});await api('settings-save',{revision:settings.revision,settings:{...settings,teams:$('[name=teams]',el).value.split(',').map(x=>x.trim()).filter(Boolean),crewAssignments}});notify('Crew assignments saved.');});};const pf=$('#permission-form');if(pf){const sync=()=>{const grant=(out.permissions||[]).find(g=>g.key===$('[name=userId]',pf).value)?.data||{};for(const flag of ['recognition','updates','operationalManager'])$('[name='+flag+']',pf).checked=!!grant[flag];$('[name=operationalManager]',pf).disabled=staff.find(s=>s.id===$('[name=userId]',pf).value)?.role!=='owner';};$('[name=userId]',pf).onchange=sync;sync();}if(pf)pf.onsubmit=e=>{e.preventDefault();run(async()=>{const d=new FormData(pf);await api('permission',{userId:d.get('userId'),operationalManager:d.has('operationalManager'),recognition:d.has('recognition'),updates:d.has('updates'),teams:(out.permissions||[]).find(g=>g.key===d.get('userId'))?.data?.teams||[]});notify('Individual permissions saved.');});};}
async function formAdmin(form){const out=await api('form-admin',{form});const current=out.current||out.form||out;const draft=out.draft||current.draft;const definition=structuredClone(draft?.definition||current.definition||{title:form.toUpperCase(),description:'',fields:[]});const fields=definition.fields||[];const el=$('#definition-editor');el.innerHTML=`<h3>${form.toUpperCase()} · published ${esc(current.version||current.formVersion||'0.1.0')}</h3><p class="muted">Changing the meaning of a question should use a new key. Existing answers retain the exact published definition.</p><form id="form-definition">${uiInput('title','Form title','text',definition.title,'required')}${uiInput('description','Form description','text',definition.description||'')}<div id="definition-fields"></div><button type="button" id="add-field">Add question</button>${uiInput('summary','Change summary','text',draft?.summary||'')}<div class="actions"><button type="button" id="preview-definition">Preview draft</button><button>Save draft</button>${S.user.role==='owner'?'<button type="button" id="publish-form" class="primary">Publish new version</button>':''}</div></form><div id="definition-preview"></div>`;function paint(){ $('#definition-fields').innerHTML=fields.map((f,i)=>`<details class="question-editor"><summary>${i+1}. ${esc(f.label||'New question')}</summary><div data-field-index="${i}" class="two-col">${uiInput('key','Stable question key','text',f.key||'','required')}${uiInput('label','Question label','text',f.label||'','required')}${uiSelect('type','Answer type',['text','textarea','number','score','select','multi','checkbox'],f.type)}${uiInput('page','Page / section','number',f.page||1,'min="1"')}${uiSelect('phase','Shift phase',['all','bod','changeover','eod'],f.phase||'all')}${uiInput('options','Options (comma separated)','text',(f.options||[]).map(o=>typeof o==='string'?o:o.label||o.name||o.value).join(', '))}<label class="check"><input name="required" type="checkbox" ${f.required?'checked':''}> Required</label><label class="check"><input name="active" type="checkbox" ${f.active!==false?'checked':''}> Active</label></div><div class="actions"><button type="button" data-move-field="${i}" data-direction="-1" ${i===0?'disabled':''}>Move up</button><button type="button" data-move-field="${i}" data-direction="1" ${i===fields.length-1?'disabled':''}>Move down</button></div></details>`).join('');$$('[data-move-field]').forEach(b=>b.onclick=()=>{collectFields();const i=Number(b.dataset.moveField),j=i+Number(b.dataset.direction);[fields[i],fields[j]]=[fields[j],fields[i]];paint();X.dirty=true;});}function collectFields(){$$('[data-field-index]',el).forEach(row=>{const d={};$$('[name]',row).forEach(e=>d[e.name]=e.type==='checkbox'?e.checked:e.value);fields[Number(row.dataset.fieldIndex)]={...fields[Number(row.dataset.fieldIndex)],...d,page:Number(d.page),options:d.options.split(',').map(s=>s.trim()).filter(Boolean)};});definition.fields=fields;definition.title=$('[name=title]',el).value;definition.description=$('[name=description]',el).value;}paint();$('#preview-definition').onclick=()=>{collectFields();const preview=$('#definition-preview');preview.innerHTML=`<section class="card"><h3>Unsaved draft preview · ${esc(definition.title)}</h3><p>${esc(definition.description)}</p>${dynamicQuestions(definition,'all',[])}</section>`;$$('input,textarea,select',preview).forEach(i=>i.disabled=true);preview.scrollIntoView({block:'start',behavior:'smooth'});};$('#form-definition').oninput=()=>{X.dirty=true;};$('#add-field').onclick=()=>{collectFields();fields.push({key:'newQuestion'+(fields.length+1),label:'New question',type:'text',page:1,phase:'all',active:true});paint();X.dirty=true;};$('#form-definition').onsubmit=e=>{e.preventDefault();run(async()=>{collectFields();await api('form-draft',{form,revision:draft?.revision||current.revision||0,definition,summary:$('[name=summary]',el).value});X.dirty=false;await formAdmin(form);notify('Draft saved. Published submissions are unchanged.');});};bind('#publish-form',async()=>{if(X.dirty)throw Error('Save the draft before publishing.');if(!confirm('Publish this new form version? Historical submissions retain their original definition.'))return;await api('form-publish',{form,revision:draft?.revision||current.revision||0});await formAdmin(form);notify('New form version published.');});}

const originalLoadSession=loadSession;
loadSession=async function(){X.team=undefined;X.open=null;X.dirty=false;await originalLoadSession();};
window.addEventListener('beforeunload',e=>{if(X.dirty){e.preventDefault();e.returnValue='';}});window.addEventListener('pagehide',()=>{if(X.quickStartToken){const token=X.quickStartToken;X.quickStartToken=null;fetch('v2/production-shift-quick-cancel',{method:'POST',headers:{'Content-Type':'application/json','X-ARR-Request':'1'},body:JSON.stringify({token}),keepalive:true}).catch(()=>{});}});


function publishedDefinition(form){return S.catalog?.forms?.find(f=>f.id===form)?.definition||{fields:[]};}
function dynamicQuestions(def,phase='all',exclude=[],feedback=false,includeWork=false){const context=new Set(['workDate','shift','stage','product','team','entryType','segmentStart','segmentEnd','newStage','newProduct','helpNeeded','helpDetail','qualityStatus',...exclude]);const fields=(def?.fields||[]).filter(f=>f.active!==false&&!context.has(f.key)&&(!feedback||phase==='eod'||!REFLECTION_KEYS.has(f.key))&&(!feedback||!QUANTITY_KEYS.has(f.key)&&!REMOVED_ENTRY_KEYS.has(f.key)&&!(phase==='all'&&f.phase==='bod'))&&(phase==='all'||!f.phase||f.phase==='all'||f.phase===phase)).sort((a,b)=>(a.page||1)-(b.page||1));const render=f=>{const name='custom-'+f.key;const flags=`data-dynamic="${esc(f.key)}" data-type="${esc(f.type)}" data-phase="${esc(f.phase||'all')}" data-required="${f.required?'true':'false'}" ${f.required?'required':''}`;let control;if(f.type==='score')control=`<span class="range-label"><small>Choose a response${f.required?' (required)':' (optional)'}</small><output for="dynamic-${esc(f.key)}">Not answered</output></span><input id="dynamic-${esc(f.key)}" name="${name}" type="range" data-optional-range min="1" max="10" step="0.5" value="5" ${flags} disabled><button type="button" class="small answer-range">Answer</button><span class="range-anchors"><span>${['mood','experience'].includes(f.key)?faceIcon('sad')+' ':''}${esc(scoreAnchors(f.key)[0])}</span><span>${['mood','experience'].includes(f.key)?faceIcon('neutral')+' ':''}In between</span><span>${['mood','experience'].includes(f.key)?faceIcon('happy')+' ':''}${esc(scoreAnchors(f.key)[1])}</span></span>`;else if(f.type==='checkbox')control=`<select name="${name}" ${flags}><option value="">Not answered</option><option value="false">No</option><option value="true">Yes</option></select>`;else if(f.type==='select'||f.type==='multi')control=`<select name="${name}" ${flags} ${f.type==='multi'?'multiple':''}><option value="">Select</option>${opts(f.key==='recognitionPeople'?(S.catalog.operators||[]).filter(o=>o.id!==S.user.id).map(o=>({id:o.id,name:associateLabel(o)})):(f.options||[]),'')}</select>`;else if(f.type==='textarea')control=`<textarea name="${name}" ${flags} maxlength="2000"></textarea>`;else control=`<input name="${name}" type="${f.type==='number'?'number':'text'}" ${flags} ${f.type==='number'?'min="0"':'maxlength="2000"'}>`;return `<label class="field">${esc(f.label)}${f.required?' *':''}${control}${f.key==='recognition'?'<small>Optional appreciation. Read by Managers, A+ and individually authorized Admins—not leads. No rankings.</small>':''}</label>`;};if(feedback){const recognition=fields.filter(f=>['recognition','recognitionPeople'].includes(f.key));const worked=fields.filter(f=>f.key==='workedWell');const used=new Set([...recognition,...worked]);const remaining=fields.filter(f=>!used.has(f));return `<details class="feedback-section" ${fields.some(f=>f.required)?'open':''}><summary><span class="feedback-title">Feedback</span> <span class="pill">Optional unless marked *</span></summary><div class="feedback-content">${recognition.map(render).join('')}${worked.map(render).join('')}${remaining.filter(f=>f.required).map(render).join('')}${remaining.some(f=>!f.required)?`<section class="feedback-other-fields"><h4>Any other issues or comments to note?</h4>${remaining.filter(f=>!f.required).map(render).join('')}</section>`:''}${includeWork?optionalWork():''}</div></details>`;}return `${fields.filter(f=>f.required).map(render).join('')}${fields.some(f=>!f.required)?`<details class="optional-fields"><summary>More feedback (optional)</summary>${fields.filter(f=>!f.required).map(render).join('')}</details>`:''}`;}
function scoreAnchors(key){return ({mood:['Difficult start','Great start'],readiness:['Not yet ready','Fully ready'],sopClarity:['Unclear','Very clear'],resources:['Missing essentials','Everything needed'],experience:['Difficult','Very good'],quality:['Unsure','Very confident'],safety:['Unsafe','Very safe'],workload:['Difficult','Manageable'],teamSupport:['Unsupported','Very supported'],pride:['Dissatisfied','Very satisfied']})[key]||['Not at all','Completely'];}
function dynamicAnswers(form,phase='all',includeOptionalOtherPhases=false){const data={};$$('[data-dynamic]',form).forEach(i=>{if(i.closest('[hidden]')||i.closest('fieldset:disabled'))return;if(i.disabled){if(i.dataset.required==='true'&&(phase==='all'||i.dataset.phase==='all'||i.dataset.phase===phase))throw Error('Please answer '+(i.closest('label')?.firstChild?.textContent||i.dataset.dynamic)+'.');return;}const fp=i.dataset.phase||'all';if(phase!=='all'&&fp!=='all'&&fp!==phase&&!(includeOptionalOtherPhases&&i.dataset.required!=='true'))return;let v=i.multiple?[...i.selectedOptions].map(o=>o.value).filter(Boolean):i.value;if(v===''||Array.isArray(v)&&!v.length)return;if(['number','score'].includes(i.dataset.type))v=Number(v);if(i.dataset.type==='checkbox')v=v==='true';data[i.dataset.dynamic]=v;});return data;}
const oldProposalFields=proposalFields;
proposalFields=function(){const def=publishedDefinition('prr');if(!def.fields?.length)return oldProposalFields();return dynamicQuestions(def,'all',[]);};
const oldCollect=collect;
collect=function(form){const d=oldCollect(form);Object.assign(d,dynamicAnswers(form));for(const name of ['productChoice','newProduct'])if($(`[name="${name}"]`,form)){const value=readProduct(form,name);if(!value)throw Error('Select or enter a product.');d[name==='productChoice'?'product':name]=value;}delete d.productChoice;delete d.productOther;delete d.newProductOther;for(const key of Object.keys(d))if(key.startsWith('custom-'))delete d[key];return d;};


const oldRenderForm=renderForm;
renderForm=function(){oldRenderForm();bindProduct($('#entry-form'));bindRanges($('#entry-form')); $$('[data-dynamic]').forEach(i=>{const v=S.draft?.data?.[i.dataset.dynamic];if(v===undefined)return;if(i.multiple){for(const o of i.options)o.selected=Array.isArray(v)&&v.includes(o.value);}else{i.value=String(v);if(i.type==='range'){i.disabled=false;const label=i.closest('label');$('output',label).textContent=String(v);$('.answer-range',label).hidden=true;}}});};


function snapshotSummary(data,definition){const map=Object.fromEntries((definition?.fields||[]).map(f=>[f.key,f.label]));return Object.entries(data).filter(([,v])=>v!==''&&v!=null).map(([k,v])=>`<div class="compact-summary"><span>${esc(map[k]||labels[k]||k)}</span><span>${esc(readable(k,v))}</span></div>`).join('');}


async function associateAdmin(){const el=$('#associate-admin');try{const out=await api('associate-list');el.innerHTML=`<p>Deactivation blocks access while retaining submitted shifts and audit history.</p>${(out.operators||[]).map(o=>`<div class="compact-summary"><span>${esc(associateLabel(o))} · ${esc(o.profile?.email||'No profile email')} · ${o.active?'Active':'Inactive'}</span>${S.user.role==='owner'?`<button data-associate="${esc(o.id)}" data-active="${o.active?'false':'true'}" data-revision="${o.revision}">${o.active?'Deactivate':'Reactivate'}</button>`:''}</div>`).join('')}`;$$('[data-associate]',el).forEach(b=>b.onclick=()=>run(async()=>{if(!confirm(b.textContent+' this fictional associate account? Existing records remain.'))return;await api('associate-save',{id:b.dataset.associate,active:b.dataset.active==='true',revision:Number(b.dataset.revision)});await associateAdmin();notify('Associate access updated.');}));}catch(e){el.textContent=e.message;}}


async function dashboard(){const today=datePacific();X.insightFrom??=priorDate(today,13);X.insightTo??=today;const p=$('#panel');p.innerHTML=`<div class="page-heading"><div><p class="eyebrow">Process insight · Not worker rankings</p><h1>See the work in context.</h1><p class="muted">Recorded labor, reported operation moves and authoritative demo FGI remain separate measures.</p></div></div><form id="insight-filters" class="filters">${uiInput('from','Work date from','date',X.insightFrom)}${uiInput('to','Through','date',X.insightTo)}<button>Apply dates</button></form><div id="insight-content"></div>`;$('#insight-filters').onsubmit=e=>{e.preventDefault();run(async()=>{const d=new FormData(e.target);X.insightFrom=d.get('from');X.insightTo=d.get('to');await dashboard();});};const out=await api('dashboard',{from:X.insightFrom||'1900-01-01',to:X.insightTo||'2999-12-31'});const shifts=(out.shiftDays||[]).sort((a,b)=>a.date.localeCompare(b.date)),fgi=(out.fgiDays||[]).sort((a,b)=>a.date.localeCompare(b.date));const sum=key=>shifts.reduce((n,d)=>n+Number(d[key]||0),0);const fgTotal=fgi.reduce((n,d)=>n+Number(d.total||0),0),max=Math.max(1,...fgi.map(d=>d.total));$('#insight-content').innerHTML=`<div class="notice-line">Fictional demonstration only. Training is separate from production. Moves may represent repeated operations; they are never added to FGI.</div><div class="metrics"><div class="metric"><small>Authoritative demo FGI</small><strong>${fgTotal.toLocaleString()}</strong><small>Finished goods counted once across ${fgi.length} dates</small></div><div class="metric"><small>Recorded production hours</small><strong>${(sum('productionMinutes')/60).toFixed(1)}</strong><small>Excludes training, waiting and recorded downtime</small></div><div class="metric"><small>Training / preparation hours</small><strong>${(sum('trainingMinutes')/60).toFixed(1)}</strong><small>Visible labor; not production weighting</small></div><div class="metric"><small>Optional reported moves</small><strong>${sum('reportedCount')?sum('reportedMoves').toLocaleString():'—'}</strong><small>${sum('unreportedCount')} segments not counted · not unique finished goods</small></div></div><section class="card"><h2>Daily authoritative demo FGI</h2>${fgi.length?`<div class="bar-chart" role="img" aria-label="Daily authoritative demo FGI; exact values and product mix below">${fgi.map(d=>`<div class="bar interactive" data-chart-height="${Math.max(2,d.total/max*100)}" title="${esc(d.date)}: ${d.total} demo FGI units"></div>`).join('')}</div><div class="chart-labels"><span>${esc(fgi[0]?.date)}</span><span>${esc(fgi.at(-1)?.date)}</span></div>${fgi.map(d=>`<details><summary>${esc(d.date)} · ${Number(d.total).toLocaleString()} FGI units · revision ${esc(d.revision)}</summary><p class="muted">${esc(d.provenance==='simulated_preset'?'Generated illustrative mix':'Manually entered demo figures')}</p>${d.rows.map(r=>`<div class="compact-summary"><span>${esc(r.family)}</span><span>${Number(r.quantity).toLocaleString()}</span></div>`).join('')}</details>`).join('')}`:'<p>No FGI saved for these dates. Use FGI & allocations to enter or generate a demonstration mix.</p>'}</section><section class="card"><h2>Recorded shifts & work context</h2>${shifts.length?shifts.map(d=>`<details><summary>${esc(d.date)} · ${d.shifts} shifts · ${(d.productionMinutes/60).toFixed(1)} production hours</summary><p>${(d.trainingMinutes/60).toFixed(1)} training hours · ${Number(d.waitingMinutes||0).toFixed(0)} waiting minutes · ${d.downtimeMinutes} downtime minutes · ${d.openSegments} unfinished segments</p><p class="muted">${d.reportedCount} counted segments; ${d.unreportedCount} not counted. An unfinished duration is not assumed complete.</p>${(d.operations||[]).map(o=>`<div class="compact-summary"><span>${esc(o.operation)} · ${esc(o.product)}</span><span>${Number(o.productionMinutes).toFixed(0)} minutes · ${o.reportedCount?o.reportedMoves+' reported moves':'Not counted'}</span></div>`).join('')}</details>`).join(''):'<p>No connected shifts in these dates.</p>'}</section><section class="card"><h2>Read comparisons with context</h2><p>Same-day FGI may contain prior-day work in progress. Quantity estimates are not individual performance measurements. Review safety, quality and work notes before drawing conclusions.</p><p>Allocation revisions are available under FGI & allocations. Stale revisions never contribute to these current charts. Yield/loss analysis and SAP integration are deferred.</p></section>`;$$('[data-chart-height]').forEach(b=>b.style.height=Number(b.dataset.chartHeight)+'%');}


function defaultWorkDate(){const now=new Date(),hour=Number(new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',hour:'2-digit',hourCycle:'h23'}).format(now));const cutoff=S.catalog?.config?.cutoffHour??3;const day=datePacific(now);return hour<cutoff?priorDate(day,1):day;}
function endTimeWarning(shift,actual){const config=(S.catalog.config?.shifts||[]).find(s=>s.id===shift.shift);const start=config?.start||(shift.shift==='swing'?'15:00':'05:00'),end=config?.end||(shift.shift==='swing'?'02:00':'15:30');let day=shift.workDate;if(end<=start)day=priorDate(day,-1);try{const expected=isoStamp(day+'T'+end);return Math.abs(Date.parse(actual)-Date.parse(expected))>30*60000?' — more than 30 minutes from the expected shift end ('+timeLabel(expected)+')':'';}catch{return '';}}
async function compareAllocationMethods(){const input=X.allocationInput;const [a,b]=await Promise.all([api('allocation-preview',{...input,method:'time',adjustments:{}}),api('allocation-preview',{...input,method:'reported-first',adjustments:{}})]);const times=a.preview,reported=b.preview,selected=X.preview;$('#method-comparison').innerHTML=`<p class="muted">Independent estimate methods; none validates reported output. Adjustments remain a separate Manager choice.</p>${[...new Set([...(times.issues||[]),...(reported.issues||[])])].map(i=>`<p>${esc(i)}</p>`).join('')}<div class="table-scroll"><table class="data-table"><thead><tr><th>Associate</th><th>Reported moves</th><th>Time-only estimate</th><th>Reported-first estimate</th><th>Current preview</th></tr></thead><tbody>${times.rows.map(r=>`<tr><td>${esc(associateLabelById(r.operator||r.username))}</td><td>${r.reportedMoves==null?'Not counted':esc(r.reportedMoves)+(r.partialReported?' (partial)':'')}</td><td>${r.allocated??'Unresolved'}</td><td>${reported.rows.find(v=>v.operator===r.operator)?.allocated??'Unresolved'}</td><td>${selected.rows.find(v=>v.operator===r.operator)?.allocated??'Unresolved'}</td></tr>`).join('')}</tbody></table></div>`;}


const previousShowLogin=showLogin;showLogin=function(){S.entries=[];S.selected=null;S.draft=null;X.shifts=[];X.productHours={};X.allocations=[];X.preview=null;X.open=null;X.lastTouchedShift=null;X.fgi=null;X.team=undefined;X.historyInitialized=false;X.dirty=false;previousShowLogin();};


async function associateLanding(){
 const p=$('#panel'),today=defaultWorkDate();
 p.innerHTML='<div class="loading">Opening your shift…</div>';
 const out=await api('shift-list',{from:'1900-01-01',to:'2999-12-31'});X.shifts=out.shifts||[];
 const active=X.shifts.find(s=>(s.segments||[]).some(v=>!v.end));
 const current=active||X.shifts.find(s=>s.workDate===today);
 X.open=null;
 p.innerHTML=`<div class="page-heading"><div><p class="eyebrow">Achievement Recognition Review</p><h1>${current?(active?'Continue your shift.':'Your shift is recorded.'):'Begin your shift.'}</h1><p class="muted">${current?`${esc(current.workDate)} · ${esc(current.shift)} · ${esc(statusShift(current.status))}${active&&current.workDate!==today?' · Previous work date—finish this shift before starting another.':''}`:'A quick start. Quality and safety come first.'}</p></div><button id="view-shift-history">Shift history</button></div><div id="shift-create"></div><div id="shift-list">${current?`<article class="queue-item"><div id="shift-${esc(current.id)}" hidden></div></article>`:''}</div>`;
 bind('#view-shift-history',async()=>{if(X.dirty&&!confirm('Discard unsaved changes?'))return;X.dirty=false;S.tab='shift-history';await render();});
 if(current)await openShift(current.id);else await startShiftForm();
}
run(loadSession);

function stationQrValidation(){
 const el=$('#station-qr-validation');if(!el)return;
 const entries=globalThis.ARRStationQR?.list?.()||[];
 el.innerHTML=`<p>Station codes are registered for Begin Shift and changeover. End Shift code: ARR-ACTION:1:end-shift (active-shift review only). Checking a code here does not log work, start a shift, or change a record. Creation and deactivation controls are not available yet.</p><label class="field">QR text to check<input id="station-qr-check-input" placeholder="ARR-STATION:1:…" autocomplete="off" autocapitalize="off" spellcheck="false"></label><button type="button" id="station-qr-check">Check QR text</button><p id="station-qr-check-result" role="status"></p><ul class="station-qr-catalog">${entries.map(a=>`<li><strong>${esc(a.stage)} — ${esc(a.product)}</strong><br><code>${esc('ARR-STATION:1:'+a.id)}</code><br><small>Registered · Begin Shift / Changeover</small></li>`).join('')}</ul>`;
 $('#station-qr-check').onclick=()=>{const a=ARRStationQR.parse($('#station-qr-check-input').value);$('#station-qr-check-result').textContent=a?(a.action==='end'?'Recognized: End Shift / End of Day. Opens review on an active shift; confirmation is required.':'Recognized: '+a.stage+' — '+a.product+'. No shift saved.'):'Not recognized. Check the full printed QR text.';};
}
